python3 -c "
import csv,collections,json,math
sq={i*i for i in range(1,11)}; p2={2**i for i in range(0,7)}; p3={1,3,9,27,81}
pr={n for n in range(2,101) if all(n%d for d in range(2,int(n**.5)+1))}
cats={'sq':sq,'p2':p2,'p3':p3,'pr':pr}
r=list(csv.DictReader(open('responses.csv')))
pool=json.load(open('novelty_pool.json'))
def cat(ns):
  xs=[int(x) for x in ns.split(',')]
  return [k for k,s in cats.items() if len(xs)>=2 and all(x in s for x in xs)]
agg=collections.defaultdict(list)
for x in r:
  for k in cat(x['number_set']):
    agg[(x['number_set'],k,int(x['target']) in cats[k])].append(int(x['rating']))
for k,v in sorted(agg.items()): print(k,len(v),round(sum(v)/len(v),2))
n=sum(1 for x in pool if any(int(x['target']) in cats[k] for k in cat(x['number_set'])))
print('pool fires',n, sum(1 for x in pool if cat(x['number_set'])))
"

